    vline.attr("x1", xScale(state.x)).attr("x2", xScale(state.x));
    hline.attr("y1", yScale(state.y)).attr("y2", yScale(state.y));
    emit();                              // &lt;-- notify dependents
  }

  // RAF throttle for move
  let raf = 0;
  function scheduleUpdate(e) {
    if (raf) return;
    raf = requestAnimationFrame(() =&gt; { raf = 0; setFromEvent(e); });
  }

  function setDragging(on) {
    if (state.dragging === on) return;
    state.dragging = on;
    emit();                              // &lt;-- notify on drag state changes too
  }

  hit.addEventListener("pointerdown", (e) =&gt; {
    setDragging(true);
    setFromEvent(e);
    hit.setPointerCapture(e.pointerId);
  });

  hit.addEventListener("pointermove", (e) =&gt; {
    if (state.dragging) scheduleUpdate(e);
  });

  const endDrag = () =&gt; setDragging(false);
  hit.addEventListener("pointerup", endDrag);
  hit.addEventListener("pointercancel", endDrag);
  hit.addEventListener("pointerleave", endDrag);

  hit.addEventListener("keydown", (e) =&gt; {
    const xStep = (muDomain[1] - muDomain[0]) / 50;
    const yStep = (sig2Domain[1] - sig2Domain[0]) / 50;
    if (e.key === "ArrowLeft") state.x -= xStep;
    else if (e.key === "ArrowRight") state.x += xStep;
    else if (e.key === "ArrowDown") state.y -= yStep;
    else if (e.key === "ArrowUp") state.y += yStep;
    else return;

    e.preventDefault();
    state.x = Math.min(Math.max(muDomain[0], state.x), muDomain[1]);
    state.y = Math.min(Math.max(sig2Domain[0], state.y), sig2Domain[1]);
    vline.attr("x1", xScale(state.x)).attr("x2", xScale(state.x));
    hline.attr("y1", yScale(state.y)).attr("y2", yScale(state.y));
    emit();
  });

  // initial notify
  queueMicrotask(emit);

  return wrap;                           // &lt;-- the view element
}

